"""Command-line management of a local package namespace repository."""

import argparse
import json
import os
from pathlib import Path
import sys
import tempfile

from .grants import GrantError
from .metadata import RepositoryIndex
from .normalize import normalize_name
from .uploads import UploadConflictError, authorize_upload

__all__ = ["CONFLICT_EXIT", "build_parser", "main"]

CONFLICT_EXIT = 3


def build_parser():
    """Build the parser for ``python -m packagenamespaces``."""
    parser = argparse.ArgumentParser(
        prog="packagenamespaces",
        description="Manage implicit package namespaces in a local JSON store."
    )
    parser.add_argument("--store", default="packagenamespaces.json",
                        help="store file (default: %(default)s)")
    commands = parser.add_subparsers(dest="command", required=True)
    for command, help_text in (
        ("reserve", "reserve a namespace"),
        ("list", "list namespace grants"),
        ("show", "show namespace details"),
        ("remove", "remove a namespace grant"),
        ("register", "record a project's owner"),
        ("grandfather", "record a project and exempt its uploads"),
        ("check-upload", "check upload authorization"),
        ("dump", "print repository JSON metadata"),
    ):
        subparser = commands.add_parser(command, help=help_text)
        # Accept --store on either side of the command without replacing a
        # value supplied to the top-level parser.
        subparser.add_argument("--store", default=argparse.SUPPRESS,
                               help="store file")
        if command in {"reserve", "show", "remove"}:
            subparser.add_argument("namespace")
        if command in {"register", "grandfather", "check-upload"}:
            subparser.add_argument("project")
        if command in {"reserve", "register", "grandfather", "check-upload"}:
            subparser.add_argument("--owner", required=True)
        if command in {"list", "show"}:
            subparser.add_argument("--json", action="store_true")
        if command == "dump":
            subparser.add_argument("--project")
    return parser


def _load_store(path):
    index = RepositoryIndex()
    try:
        with path.open(encoding="utf-8") as stream:
            data = json.load(stream)
    except FileNotFoundError:
        return index
    if (not isinstance(data, dict)
            or set(data) != {"grants", "projects", "grandfathered"}
            or not isinstance(data["grants"], dict)
            or not isinstance(data["projects"], dict)
            or not isinstance(data["grandfathered"], list)):
        raise ValueError("invalid store schema")
    for name, owner in data["grants"].items():
        index.store.reserve(name, owner)
    for project, owner in data["projects"].items():
        index.register_project(project, owner)
    for project in data["grandfathered"]:
        index.grandfathered.add(project)
    return index


def _save_store(path, index):
    data = {
        "grants": {name: index.store.get(name).owner
                   for name in index.store.namespaces()},
        "projects": {name: index.project_owner(name)
                     for name in index.projects()},
        "grandfathered": index.grandfathered.projects(),
    }
    # Replace only after the complete new state has been written successfully.
    temporary = None
    try:
        with tempfile.NamedTemporaryFile(
            mode="w", encoding="utf-8", dir=path.parent, delete=False,
        ) as stream:
            temporary = stream.name
            json.dump(data, stream, indent=2, sort_keys=True)
            stream.write("\n")
        os.replace(temporary, path)
    finally:
        if temporary is not None and os.path.exists(temporary):
            os.unlink(temporary)


def _run(args, path, index):
    command = args.command
    if command == "reserve":
        grant = index.store.reserve(args.namespace, args.owner)
        _save_store(path, index)
        print(f"reserved {grant.name} for {grant.owner}")
    elif command == "remove":
        index.store.remove(args.namespace)
        _save_store(path, index)
        print(f"removed {normalize_name(args.namespace)}")
    elif command in {"register", "grandfather"}:
        index.register_project(args.project, args.owner)
        project = normalize_name(args.project)
        if command == "grandfather":
            index.grandfathered.add(project)
        _save_store(path, index)
        if command == "register":
            print(f"registered {project} for {args.owner}")
        else:
            print(f"grandfathered {project}")
    elif command == "list":
        grants = [{"name": name, "owner": index.store.get(name).owner}
                  for name in index.store.namespaces()]
        if args.json:
            print(json.dumps(grants))
        else:
            for grant in grants:
                print(f"{grant['name']} {grant['owner']}")
    elif command == "show":
        detail = index.namespace_detail(args.namespace)
        if args.json:
            print(json.dumps(detail))
        else:
            print(f"name: {detail['name']}")
            print(f"owner: {detail['owner']}")
            print(f"parent: {detail['parent'] or 'none'}")
            print(f"children: {', '.join(detail['children']) or 'none'}")
    elif command == "check-upload":
        authorize_upload(args.project, args.owner, index.store,
                         index.grandfathered)
        print(f"OK {normalize_name(args.project)}")
    elif command == "dump":
        if args.project is not None:
            detail = index.project_detail(args.project)
        else:
            detail = {"api_version": index.api_version,
                      "namespaces": index.list_namespaces()}
        print(json.dumps(detail))


def main(argv=None):
    """Run the CLI and return 0, 1 (error), or 3 (upload conflict)."""
    args = build_parser().parse_args(argv)
    try:
        path = Path(args.store)
        index = _load_store(path)
        _run(args, path, index)
    except UploadConflictError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return CONFLICT_EXIT
    except (GrantError, OSError, ValueError, TypeError) as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1
    return 0
