API_VERSION = "1.5"
LEGACY_API_VERSION = "1.4"


class NotSupportedError(Exception):
    """The repository does not support namespace metadata."""


class RepositoryIndex:
    """Model project ownership and namespace metadata for one repository."""

    def __init__(self, store=None, *, supports_namespaces=True,
                 grandfathered=None):
        self.store = GrantStore() if store is None else store
        self.supports_namespaces = supports_namespaces
        self.grandfathered = (GrandfatheredRegistry() if grandfathered is None
                              else grandfathered)
        self._projects = {}

    @property
    def api_version(self):
        """The JSON API version supported by this repository."""
        return API_VERSION if self.supports_namespaces else LEGACY_API_VERSION

    def register_project(self, project, owner):
        """Record project ownership independently of upload authorization."""
        _validate_owner(owner)
        self._projects[_validated_name(project)] = owner

    def project_owner(self, project):
        """Return the recorded owner, or None for an unknown project."""
        return self._projects.get(_validated_name(project))

    def projects(self):
        """Return registered project names in sorted order."""
        return sorted(self._projects)

    def project_detail(self, project):
        """Return project metadata, including current namespace ownership."""
        project = _validated_name(project)
        detail = {"name": project}
        if self.supports_namespaces:
            owner = self.project_owner(project)
            matches = [
                {"name": grant.name, "owned": owner == grant.owner}
                for grant in self.store.matching(project)
            ]
            detail["namespaces"] = matches or None
        return detail

    def _require_namespaces(self):
        if not self.supports_namespaces:
            raise NotSupportedError("repository does not support namespaces")

    def list_namespaces(self):
        """Return the bare sorted list served at /namespaces."""
        self._require_namespaces()
        return [{"name": name} for name in self.store.namespaces()]

    def namespace_detail(self, namespace):
        """Return metadata served at /namespace/<namespace>."""
        self._require_namespaces()
        namespace = _validated_name(namespace)
        grant = self.store.get(namespace)
        if grant is None:
            raise UnknownGrantError(f"unknown grant: {namespace}")
        return {
            "name": namespace,
            "parent": self.store.parent(namespace),
            "children": self.store.children(namespace),
            "owner": grant.owner,
        }

    def simple_html(self, project, files=()):
        """Render a full HTML Simple API page without namespace metadata.

        Each file is a mapping containing 'filename' and 'url'.
        """
        name = escape(project)
        lines = [
            "<!DOCTYPE html>",
            "<html>",
            f"<head><title>Links for {name}</title></head>",
            "<body>",
            f"<h1>Links for {name}</h1>",
        ]
        for file in files:
            url = escape(file["url"], quote=True)
            filename = escape(file["filename"])
            lines.append(f'<a href="{url}">{filename}</a><br>')
        lines.extend(["</body>", "</html>"])
        return "\n".join(lines) + "\n"
