"""Repository-local namespace checks for installers."""

from .grants import InvalidNamespaceError, _validated_name, _validate_owner
from .matching import namespace_matches

__all__ = ["SecurityPolicy"]


class SecurityPolicy:
    """Require projects and matching namespace grants to have one owner."""

    def __init__(self, namespaces, owner):
        _validate_owner(owner)
        if isinstance(namespaces, str):
            namespaces = (namespaces,)
        try:
            self._namespaces = tuple(_validated_name(name)
                                     for name in namespaces)
        except TypeError:
            raise InvalidNamespaceError(
                "namespaces must be an iterable of names"
            ) from None
        self._owner = owner

    @property
    def namespaces(self):
        """The normalized policy namespaces as a tuple."""
        return self._namespaces

    @property
    def owner(self):
        """The required project and grant owner."""
        return self._owner

    def allows(self, project, index):
        """Return whether *index* satisfies this policy for *project*."""
        project = _validated_name(project)
        if (not index.supports_namespaces
                or index.project_owner(project) != self.owner):
            return False
        for namespace in self.namespaces:
            grant = index.store.get(namespace)
            if (grant is not None and grant.owner == self.owner
                    and namespace_matches(namespace, project)):
                return True
        return False

    def evaluate(self, requirements, index):
        """Map normalized project names to their policy decisions."""
        return {_validated_name(project): self.allows(project, index)
                for project in requirements}
