"""Upload authorization and exemptions for preexisting projects."""

from .grants import _validated_name, _validate_owner

__all__ = [
    "CONFLICT_STATUS", "UploadConflictError", "GrandfatheredRegistry",
    "authorize_upload",
]

CONFLICT_STATUS = 409


class UploadConflictError(Exception):
    """An upload conflicts with a namespace grant (HTTP 409 Conflict)."""

    status_code = CONFLICT_STATUS

    def __init__(self, project, namespace, owner):
        self.project = project
        self.namespace = namespace
        self.owner = owner
        super().__init__(
            f"409 Conflict: {project!r} matches reserved namespace "
            f"{namespace!r}; uploader {owner!r} is not authorized"
        )


class GrandfatheredRegistry:
    """Track normalized project names exempt from upload restrictions."""

    def __init__(self, projects=()):
        self._projects = set()
        for project in projects:
            self.add(project)

    def __len__(self):
        return len(self._projects)

    def __contains__(self, project):
        return self.covers(project)

    def add(self, project):
        """Exempt *project* from namespace upload restrictions."""
        self._projects.add(_validated_name(project))

    def discard(self, project):
        """Remove an exemption if present."""
        self._projects.discard(_validated_name(project))

    def covers(self, project):
        """Return whether the normalized project has an exemption."""
        return _validated_name(project) in self._projects

    def projects(self):
        """Return exempt project names in sorted order."""
        return sorted(self._projects)


def authorize_upload(project, owner, store, grandfathered=None):
    """Return True for an allowed upload, otherwise raise UploadConflictError.

    Validate the uploader before consulting grants or exemptions.
    """
    _validate_owner(owner)
    project = _validated_name(project)
    if grandfathered is not None and grandfathered.covers(project):
        return True
    for grant in store.matching(project):
        if grant.owner != owner:
            raise UploadConflictError(project, grant.name, owner)
    return True
